template <typename Key>
void HeapTimer<Key>::Clear() noexcept {
    nodes_.clear();
    key_to_idx_.clear();
}

template <typename Key>
bool HeapTimer<Key>::Empty() const noexcept {
    assert(nodes_.empty() == key_to_idx_.empty());
    return nodes_.empty();
}

template <typename Key>
std::size_t HeapTimer<Key>::Size() const noexcept {
    assert(nodes_.size() == key_to_idx_.size());
    return nodes_.size();
}

class Buffer {
public:
    //! Create a buffer with an initial size.
    explicit Buffer(std::size_t size = 1000) noexcept;

    //! Create a buffer with bytes.
    explicit Buffer(std::span<const std::byte> bytes) noexcept;

    //! Create a buffer with bytes.
    explicit Buffer(std::initializer_list<std::byte> bytes) noexcept;

    //! Create a buffer with a string.
    explicit Buffer(std::string_view str) noexcept;

    Buffer(const Buffer&) noexcept;

    Buffer(Buffer&&) noexcept;

    Buffer& operator=(const Buffer&) noexcept;

    Buffer& operator=(Buffer&&) noexcept;

    //! Get the current writable size without expanding.
    std::size_t WritableSize() const noexcept;

    //! Get the readable size.
    std::size_t ReadableSize() const noexcept;

    //! Peek the first byte without moving the reading offset.
    std::optional<std::byte> Peek() const noexcept;

    //! Get readable bytes without moving the reading offset.
    std::span<const std::byte> ReadableBytes() const noexcept;

    /**
     * @brief Get a readable string without moving the reading offset.
     *
     * @warning Developers should ensure that the stored bytes are printable.
     */
    std::string ReadableString() const noexcept;

    /**
     * @brief Get writable space for editing.
     *
     * @warning
     * If developers directly write data using the base address of writable space,
     * they must manually adjust the writing offset with @p HasWritten.
     */
    std::span<std::byte> WritableBytes() const noexcept;

    //! Append bytes to the buffer and move forward the writing offset.
    void Append(std::span<const std::byte> bytes) noexcept;

    //! Append bytes to the buffer and move forward the writing offset.
    void Append(std::initializer_list<std::byte> bytes) noexcept;

    //! Append a string and an optional new-line character to the buffer and move forward the writing offset.
    void Append(std::string_view str,
                std::optional<NewLine> new_line = std::nullopt) noexcept;

    //! Append data to the buffer and move forward the writing offset.
    void Append(const void* data, std::size_t size) noexcept;

    //! Append another buffer to the buffer and move forward the writing offset.
    void Append(const Buffer& buf) noexcept;

    //! Ensure the buffer has enough writable space.
    void EnsureWriteableSize(std::size_t size) noexcept;

    //! Manually move forward the writing offset by a specific size.
    void HasWritten(std::size_t size) noexcept;

    //! Manually move forward the reading offset by a specific size.
    void Retrieve(std::size_t size) noexcept;

    //! Manually move forward the reading offset until it reaches the destination.
    std::size_t RetrieveUntil(const void* addr) noexcept;

    //! Manually move forward the reading offset to the end.
    std::size_t RetrieveAll() noexcept;

    /**
     * @brief Manually move forward the reading offset to the end and extract a string from the rest.
     *
     * @warning Developers should ensure that the stored bytes are printable.
     */
    std::string RetrieveAllToString() noexcept;

    //! Clear the buffer.
    void Clear() noexcept;

    //! Whether the buffer is empty.
    bool Empty() const noexcept;

protected:
    //! Get the prependable size which can be reused.
    std::size_t PrependableSize() const noexcept;

    //! Make the buffer have enough writable space.
    void MakeSpace(std::size_t size) noexcept;

    //! Get the reading offset.
    std::vector<std::byte>::iterator ReadIter() const noexcept;

    //! Get the writing offset.
    std::vector<std::byte>::iterator WriteIter() const noexcept;

    std::vector<std::byte> buf_;
    std::atomic<std::size_t> read_pos_ {0};
    std::atomic<std::size_t> write_pos_ {0};
}

template <typename Key>
class HeapTimer {
public:
    using Clock = std::chrono::steady_clock;

    using TimeOutCallback = std::function<void(const Key&)>;

    /**
     * @brief Create a timer system.
     *
     * @param logger
     * A logger. If it is @p nullptr, the timer system will use the global root logger.
     */
    explicit HeapTimer(log::Logger::Ptr logger = log::RootLogger()) noexcept;

    HeapTimer(HeapTimer&&) = delete;

    HeapTimer& operator=(HeapTimer&&) = delete;

    HeapTimer(const HeapTimer&) = delete;

    HeapTimer& operator=(const HeapTimer&) = delete;

    /**
     * @brief Adjust a node's expiration time.
     *
     * @param key A key.
     * @param expiration A new duration from now to its expiration time.
     *
     * @exception std::out_of_range The timer system does not contain any node with the specific key.
     */
    void Adjust(const Key& key, Clock::duration expiration);

    /**
     * @brief Adjust a node's expiration time.
     *
     * @param key A key.
     * @param expiration A new expiration time.
     *
     * @exception std::out_of_range The timer system does not contain any node with the specific key.
     */
    void Adjust(const Key& key, Clock::time_point expiration);

    /**
     * @brief Push a node into the timer system.
     *
     * @param key A key.
     * @param expiration A duration from now to its expiration time.
     * @param callback A time-out callback that will be invoked when the node expires.
     */
    void Push(const Key& key, Clock::duration expiration,
              TimeOutCallback callback) noexcept;

    /**
     * @brief Push a node into the timer system.
     *
     * @param key A key.
     * @param expiration An expiration time.
     * @param callback A time-out callback that will be invoked when the node expires.
     */
    void Push(const Key& key, Clock::time_point expiration,
              TimeOutCallback callback) noexcept;

    /**
     * @brief Remove expired nodes and invoke their callbacks.
     *
     * @warning
     * Any exceptions raised in callbacks will not be rethrown.
     * Exception messages will be recorded in the logger.
     */
    void Tick() noexcept;

    /**
     * @brief Remove a node by its key.
     *
     * @return Whether the node was removed.
     */
    bool Remove(const Key& key) noexcept;

    /**
     * @brief Remove a node by its key and invoke the callback.
     *
     * @exception std::out_of_range The timer system does not contain any node with the specific key.
     *
     * @warning
     * Any exceptions raised in callbacks will not be rethrown.
     * Exception messages will be recorded in the logger.
     */
    void Invoke(const Key& key);

    /**
     * @brief Pop the top node and return its key.
     *
     * @warning This method can only be called when the timer system is not empty.
     */
    Key Pop() noexcept;

    //! Clear the timer system.
    void Clear() noexcept;

    //! Whether the timer system contains the node with a specific key.
    bool Contain(const Key& key) const noexcept;

    //! Whether the timer system is empty.
    bool Empty() const noexcept;

    //! Get the number of nodes.
    std::size_t Size() const noexcept;

    /**
     * @brief
     * Remove expired nodes and invoke their callbacks.
     * Then return the interval from now to the next node's expiration time.
     * The interval is greater than or equal to zero.
     *
     * @warning
     * Any exceptions raised in callbacks will not be rethrown.
     * Exception messages will be recorded in the logger.
     */
    Clock::duration ToNextTick() noexcept;

private:
    struct Node {
        //! A user-defined unique key.
        Key key;

        //! An expiration time.
        Clock::time_point expiration;

        //! A time-out callback which will be invoked when the node expires.
        TimeOutCallback callback;

        //! Whether the node has expired.
        bool Expired() const noexcept;

        void Swap(Node&) noexcept;

        friend std::weak_ordering operator<=>(const Node& lhs,
                                              const Node& rhs) noexcept {
            return lhs.expiration <=> rhs.expiration;
        }
    };

    void Swap(std::size_t idx1, std::size_t idx2) noexcept;

    /**
     * @brief Adjust a node.
     *
     * @exception std::out_of_range The timer system does not contain any node with the specific key.
     */
    void Adjust(const Key& key, Clock::time_point expiration,
                std::optional<TimeOutCallback> callback);

    //! Remove a node and return its key.
    Key RemoveByIndex(std::size_t idx) noexcept;

    /**
     * @brief
     * Recursively swap a node with its parent if it is smaller than the parent.
     *
     * @details
     * This method will continue shift-up even if the parent is equal to the node.
     * Finally, the node will be moved to the top of other nodes with the same value.
     */
    void ShiftUp(std::size_t idx) noexcept;

    //! Recursively swap a node with its smallest child if it is larger than the child.
    void ShiftDown(std::size_t idx) noexcept;

    bool ValidIndex(std::size_t idx) const noexcept;

    //! Get the index of a node's parent, or @p std::nullopt if it does not exist.
    std::optional<std::size_t> Parent(std::size_t idx) const noexcept;

    /**
     * @brief
     * Get the index of a node's child that has a shorter expiration time,
     * or @p std::nullopt if it does not exist.
     */
    std::optional<std::size_t> SmallChild(std::size_t idx) const noexcept;

    log::Logger::Ptr logger_;

    //! A map from user-defined keys to array indices.
    std::unordered_map<Key, std::size_t> key_to_idx_;
    std::deque<Node> nodes_;
};

template <typename Key>
HeapTimer<Key>::HeapTimer(log::Logger::Ptr logger) noexcept :
    logger_ {std::move(logger)} {
    if (!logger_) {
        logger_ = log::RootLogger();
    }
}

template <typename Key>
Key HeapTimer<Key>::RemoveByIndex(const std::size_t idx) noexcept {
    assert(ValidIndex(idx));
    const auto key {nodes_[idx].key};
    if (Size() == 1) {
        Clear();
        return key;
    }

    // Assign the minimum value to the input node.
    nodes_[idx].expiration = Clock::time_point {Clock::duration::zero()};
    ShiftUp(idx);

    // The input node will be at the top.
    assert(nodes_.front().key == key);

    // Swap the top and the last node.
    nodes_.front().Swap(nodes_.back());
    std::swap(key_to_idx_[nodes_.front().key], key_to_idx_[nodes_.back().key]);

    // Delete the input node.
    nodes_.pop_back();
    key_to_idx_.erase(key);

    // Move the top node to the correct place.
    ShiftDown(0);

    assert(key_to_idx_.size() == nodes_.size());
    return key;
}

template <typename T, typename FromStr = VarConverter<std::string, T>,
          typename ToStr = VarConverter<T, std::string>>
requires std::is_invocable_r_v<T, FromStr, std::string> && std::
    is_nothrow_invocable_r_v<std::string, ToStr, T>
class Var : public VarBase {
public:
    using Ptr = std::shared_ptr<Var>;

    /**
     * @brief The listener for value change events.
     *
     * @param old_val The old value before changing.
     * @param new_val The new value after changing.
     */
    using OnChange = std::function<void(const T& old_val, const T& new_val)>;

    explicit Var(const std::string_view name, const T& default_val,
                 const std::string_view description = "") noexcept :
        VarBase {name, description}, val_ {default_val} {}

    Var(const Var&) = delete;

    Var(Var&&) = delete;

    Var& operator=(const Var&) = delete;

    Var& operator=(Var&&) = delete;

    std::string ToString() const noexcept override {
        return ToStr {}(GetValue());
    }

    void FromString(const std::string_view str) override {
        SetValue(FromStr {}(str));
    }

    T GetValue() const noexcept {
        const std::shared_lock locker {mtx_};
        return val_;
    }

    void SetValue(const T& val) noexcept {
        {
            const std::shared_lock locker {mtx_};
            if (val != val_) {
                std::ranges::for_each(
                    listeners_, [&val, this](const auto& listener) noexcept {
                        try {
                            listener.second(val_, val);
                        } catch (const std::exception& err) {
                            std::osyncstream {std::cerr} << err.what()
                                                         << std::endl;
                        }
                    });
            }
        }

        const std::unique_lock locker {mtx_};
        val_ = val;
    }

    //! Get a unique string representing the variable type.
    std::string_view TypeName() const noexcept {
        return typeid(T).name();
    }

    /**
     * @brief Remove a listener.
     *
     * @param key A unique key corresponding to the listener.
     */
    void RemoveListener(const std::uint64_t key) noexcept {
        const std::unique_lock locker {mtx_};
        listeners_.erase(key);
    }

    /**
     * @brief Add a listener for value change events.
     *
     * @param listener A listener.
     * @return A unique key corresponding to the listener.
     */
    std::uint64_t AddListener(OnChange listener) noexcept {
        const std::unique_lock locker {mtx_};
        static std::uint64_t key {0};
        listeners_[key] = std::move(listener);
        return key++;
    }

    //! Remove all listeners.
    void ClearListeners() noexcept {
        const std::unique_lock locker {mtx_};
        listeners_.clear();
    }

private:
    mutable std::shared_mutex mtx_;

    T val_;
    std::unordered_map<std::uint64_t, OnChange> listeners_;
};

Logger::Logger(const std::string_view name, const log::Level level,
               const std::optional<std::size_t> capacity) noexcept :
    name_ {name}, level_ {level}, capacity_ {capacity.value_or(0)} {
    if (capacity_ > 0) {
        async_ = true;
        event_deque_ = std::make_unique<BlockDeque<Event::Ptr>>(capacity_);
        writer_thread_ =
            std::make_unique<std::thread>(&Logger::AsyncLogProc, this);
    } else {
        async_ = false;
    }
}

template <typename T>
class VarConverter<std::list<T>, std::string> {
public:
    std::string operator()(const std::list<T>& vals) const noexcept {
        YAML::Node node;
        std::ranges::for_each(vals, [&node](const T& val) {
            node.push_back(
                LoadYamlString(VarConverter<T, std::string> {}(val)));
        });

        std::ostringstream ss;
        ss << node;
        return ss.str();
    }
};

template <typename T>
class VarConverter<std::vector<T>, std::string> {
public:
    std::string operator()(const std::vector<T>& vals) const noexcept {
        return VarConverter<std::list<T>, std::string> {}(
            {vals.cbegin(), vals.cend()});
    }
};
